import { IToolDefinition, RunDiagnosticsParams, RunDiagnosticsParamsSchema, ToolExecutionContext, ToolResult } from '@moderado/contracts';
import { parseTypeScriptDiagnostics, runDiagnosticScript } from '../diagnostics.js';
export const RunDiagnosticsTool: IToolDefinition<RunDiagnosticsParams> = { name:'run_diagnostics', description:'Run an approved TypeScript/JavaScript diagnostic script.', requiresApproval:true, parametersSchema:RunDiagnosticsParamsSchema, async execute(params:RunDiagnosticsParams, context:ToolExecutionContext):Promise<ToolResult>{try{const run=await runDiagnosticScript(context.workspaceRoot,params.script); const diagnostics=parseTypeScriptDiagnostics(run.output); return {toolName:'run_diagnostics',status:'success',output:run.output||`npm run ${params.script} exited with code ${run.exitCode}`,metadata:{diagnostics,exitCode:run.exitCode}};}catch(err:any){return {toolName:'run_diagnostics',status:'error',output:err.message};}} };